from AlgorithmImports import *
from datetime import timedelta, time


class FiveMinuteSpyCallCrossover(QCAlgorithm):
    def Initialize(self):
        self.SetTimeZone(TimeZones.NewYork)
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)

        self.spy = self.AddEquity("SPY", Resolution.Minute, Market.USA, False).Symbol
        self.Securities[self.spy].SetDataNormalizationMode(DataNormalizationMode.Raw)

        self.option = self.AddOption("SPY", Resolution.Minute, Market.USA)
        self.option.SetFilter(
            lambda u: u.IncludeWeeklys()
                       .Strikes(-500, 500)
                       .Expiration(timedelta(0), timedelta(days=730))
        )
        self.option_symbol = self.option.Symbol

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)
        self.previous_fast = None
        self.previous_slow = None

        self.five_minute_consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self.five_minute_consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, self.five_minute_consolidator)

        self.entry_signal = False
        self.entry_ticket = None
        self.exit_ticket = None
        self.spy_liquidation_ticket = None

        self.held_option = None
        self.entry_price = None
        self.expiry_date = None
        self.no_entry_date = None

    def OnFiveMinuteBar(self, sender, bar):
        self.entry_signal = False

        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        crossed = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.fast.IsReady
            and self.slow.IsReady
            and self.previous_fast <= self.previous_slow
            and self.fast.Current.Value > self.slow.Current.Value
        )

        if self.fast.IsReady and self.slow.IsReady:
            self.previous_fast = self.fast.Current.Value
            self.previous_slow = self.slow.Current.Value

        if not crossed:
            return

        bar_time = bar.EndTime.time()
        if time(9, 45) <= bar_time <= time(14, 30):
            self.entry_signal = True

    def OnData(self, data):
        self._handle_unexpected_spy_position()

        if self.held_option is not None:
            self._handle_expiration_safety()
            self._handle_time_stop()
            self._handle_profit_target(data)

        if self.entry_signal:
            self.entry_signal = False
            self._try_enter(data)

    def _try_enter(self, data):
        if self.no_entry_date == self.Time.date():
            return

        if self.held_option is not None or self._ticket_open(self.entry_ticket) or self._ticket_open(self.exit_ticket):
            return

        chains = [
            chain for chain in data.OptionChains.Values
            if chain.Underlying is not None and chain.Underlying.Symbol == self.spy
        ]

        if not chains:
            self.Debug(f"{self.Time}: Entry skipped: no SPY option chain in Slice.")
            return

        contracts = []
        for chain in chains:
            contracts.extend(list(chain.Contracts.Values))

        eligible_expiries = sorted({
            contract.Expiry.date()
            for contract in contracts
            if (contract.Expiry.date() - self.Time.date()).days >= 7
        })

        if not eligible_expiries:
            self.Debug(f"{self.Time}: Entry skipped: no expiration at least 7 calendar days away.")
            return

        selected_expiry = eligible_expiries[0]
        calls = [
            contract for contract in contracts
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
        ]

        if not calls:
            self.Debug(f"{self.Time}: Entry skipped: no calls at selected expiration {selected_expiry}.")
            return

        underlying_price = self.Securities[self.spy].Price
        selected = min(calls, key=lambda c: (abs(c.Strike - underlying_price), c.Strike))

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            f"{self.Time}: Submitted entry for 1 {selected.Symbol} "
            f"(expiry {selected_expiry}, strike {selected.Strike})."
        )

    def _handle_profit_target(self, data):
        if self.entry_price is None or self._ticket_open(self.exit_ticket):
            return

        contract = self._contract_from_slice(data, self.held_option)
        if contract is None or contract.BidPrice <= 0 or contract.AskPrice <= 0:
            return

        midpoint = (contract.BidPrice + contract.AskPrice) / 2.0
        if midpoint >= self.entry_price * 1.50:
            self._submit_option_exit("profit target")

    def _handle_time_stop(self):
        if self.expiry_date is None or self._ticket_open(self.exit_ticket):
            return

        exchange_hours = self.Securities[self.spy].Exchange.Hours
        previous_trading_day = exchange_hours.GetPreviousTradingDay(self.expiry_date)

        if (
            self.Time.date() == previous_trading_day.date()
            and self.Time.hour == 15
            and self.Time.minute == 45
        ):
            self._submit_option_exit("15:45 pre-expiration time stop")

    def _handle_expiration_safety(self):
        if self.expiry_date is None:
            return

        if self.Time.date() >= self.expiry_date:
            self.no_entry_date = self.Time.date()
            if not self._ticket_open(self.exit_ticket):
                self._submit_option_exit("expiration safety")

    def _submit_option_exit(self, reason):
        if self.held_option is None:
            return

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity == 0:
            return

        self.Transactions.CancelOpenOrders(self.held_option)
        self.exit_ticket = self.MarketOrder(self.held_option, -quantity)
        self.Debug(f"{self.Time}: Submitted option exit ({reason}) for {self.held_option}.")

    def _contract_from_slice(self, data, symbol):
        for chain in data.OptionChains.Values:
            for contract in chain.Contracts.Values:
                if contract.Symbol == symbol:
                    return contract
        return None

    def _ticket_open(self, ticket):
        if ticket is None:
            return False
        return ticket.Status not in [OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid]

    def _handle_unexpected_spy_position(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity == 0:
            self.spy_liquidation_ticket = None
            return

        if not self._ticket_open(self.spy_liquidation_ticket):
            self.Debug(f"{self.Time}: Unexpected SPY equity position detected; liquidating.")
            self.spy_liquidation_ticket = self.MarketOrder(self.spy, -quantity)

    def OnOrderEvent(self, order_event):
        if order_event.OrderId == (self.entry_ticket.OrderId if self.entry_ticket else -1):
            if order_event.Status == OrderStatus.Filled and order_event.FillQuantity > 0:
                self.held_option = order_event.Symbol
                self.entry_price = order_event.FillPrice
                self.expiry_date = order_event.Symbol.ID.Date.date()
                self.entry_ticket = None
                self.Debug(
                    f"{self.Time}: Entry filled for {self.held_option} "
                    f"at {self.entry_price:.2f}."
                )
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.entry_ticket = None

        if order_event.OrderId == (self.exit_ticket.OrderId if self.exit_ticket else -1):
            if order_event.Status == OrderStatus.Filled:
                self.Debug(f"{self.Time}: Exit filled for {order_event.Symbol} at {order_event.FillPrice:.2f}.")
                self.held_option = None
                self.entry_price = None
                self.expiry_date = None
                self.exit_ticket = None
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.exit_ticket = None

        self._handle_unexpected_spy_position()

