        if self.held_option is not None or self._ticket_open(self.entry_ticket) or self._ticket_open(self.exit_ticket):
            return

        chains = [
            chain for chain in data.OptionChains.Values
            if chain.Underlying is not None and chain.Underlying.Symbol == self.spy
        ]

        if not chains:
            self.Debug(f"{self.Time}: Entry skipped: no SPY option chain in Slice.")
            return

        contracts = []
        for chain in chains:
            contracts.extend(list(chain.Contracts.Values))

        eligible_expiries = sorted({
            contract.Expiry.date()
            for contract in contracts
            if (contract.Expiry.date() - self.Time.date()).days >= 7
        })

        if not eligible_expiries:
            self.Debug(f"{self.Time}: Entry skipped: no expiration at least 7 calendar days away.")
            return

        selected_expiry = eligible_expiries[0]
        calls = [
            contract for contract in contracts
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
        ]

        if not calls:
            self.Debug(f"{self.Time}: Entry skipped: no calls at selected expiration {selected_expiry}.")
            return

        underlying_price = self.Securities[self.spy].Price
        selected = min(calls, key=lambda c: (abs(c.Strike - underlying_price), c.Strike))

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            f"{self.Time}: Submitted entry for 1 {selected.Symbol} "
            f"(expiry {selected_expiry}, strike {selected.Strike})."
        )

