        if self.entry_price is None or self._ticket_open(self.exit_ticket):
            return

        contract = self._contract_from_slice(data, self.held_option)
        if contract is None or contract.BidPrice <= 0 or contract.AskPrice <= 0:
            return

        midpoint = (contract.BidPrice + contract.AskPrice) / 2.0
        if midpoint >= self.entry_price * 1.50:
            self._submit_option_exit("profit target")

    def _handle_time_stop(self):
        if self.expiry_date is None or self._ticket_open(self.exit_ticket):
            return

        exchange_hours = self.Securities[self.spy].Exchange.Hours
        previous_trading_day = exchange_hours.GetPreviousTradingDay(self.expiry_date)

        if (
            self.Time.date() == previous_trading_day.date()
            and self.Time.hour == 15
            and self.Time.minute == 45
        ):
            self._submit_option_exit("15:45 pre-expiration time stop")

    def _handle_expiration_safety(self):
        if self.expiry_date is None:
            return

        if self.Time.date() >= self.expiry_date:
            self.no_entry_date = self.Time.date()
            if not self._ticket_open(self.exit_ticket):
                self._submit_option_exit("expiration safety")

    def _submit_option_exit(self, reason):
        if self.held_option is None:
            return

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity == 0:
