        if not self.Portfolio[self.spy_symbol].Invested or self.spy_liquidation_open:
            return

        quantity = self.Portfolio[self.spy_symbol].Quantity
        ticket = self.MarketOrder(self.spy_symbol, -quantity)

        if ticket.Status != OrderStatus.Invalid:
            self.spy_liquidation_open = True
            self.Debug(f"{self.Time}: Unexpected SPY exercise/assignment position; liquidating.")

    def HasOptionHolding(self):
        return (
            self.held_contract is not None
            and self.Portfolio[self.held_contract].Invested
        )

    def GetOptionChain(self, slice):
        try:
            return slice.OptionChains[self.option_symbol]
        except KeyError:
            return None

    def GetHeldContractFromSlice(self, slice):
        chain = self.GetOptionChain(slice)
        if chain is None:
            return None

        for contract in chain:
            if contract.Symbol == self.held_contract:
                return contract

        return None

    def OnOrderEvent(self, order_event):
        if order_event.OrderId == self.entry_ticket_id:
            if order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self.entry_order_open = False
                self.entry_ticket_id = None

            if order_event.Status == OrderStatus.Filled:
                self.entry_order_open = False
                self.entry_ticket_id = None
                self.held_contract = order_event.Symbol
                self.held_expiry_date = order_event.Symbol.ID.Date.date()
                self.entry_fill_price = order_event.FillPrice
                self.Debug(
                    f"{self.Time}: Entry filled {order_event.Symbol} at "
                    f"{order_event.FillPrice}."
                )

        if order_event.OrderId == self.exit_ticket_id:
            if order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self.exit_order_open = False
                self.exit_ticket_id = None

            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    f"{self.Time}: Exit filled {order_event.Symbol} at "
                    f"{order_event.FillPrice}."
                )
                self.exit_order_open = False
                self.exit_ticket_id = None
                self.held_contract = None
                self.held_expiry_date = None
                self.entry_fill_price = None

        if order_event.Symbol == self.spy_symbol and order_event.Status == OrderStatus.Filled:
            self.spy_liquidation_open = False

