        valid_expiries = sorted({
            contract.Expiry.date()
            for contract in contracts
            if contract.Expiry.date() >= minimum_expiry
        })

        if not valid_expiries:
            self.Debug("Entry skipped: no expiration at least 7 calendar days away.")
            return

        selected_expiry = valid_expiries[0]
        eligible_calls = [
            contract for contract in contracts
            if contract.Expiry.date() == selected_expiry
        ]

        if not eligible_calls:
            self.Debug("Entry skipped: no eligible call contracts at selected expiration.")
            return

        underlying_price = self.Securities[self.spy].Price
        selected_contract = min(
            eligible_calls,
            key=lambda contract: (abs(contract.Strike - underlying_price), contract.Strike)
        )

        self.entry_ticket = self.MarketOrder(
            selected_contract.Symbol,
            1,
            tag="Bullish 5-minute SMA crossover entry"
        )

    def CheckMinuteExit(self, data: Slice):
        if self.held_contract is None or self.entry_fill_price is None:
            return

        if self.exit_ticket is not None:
            return

        midpoint = self.GetHeldContractMidpoint(data)
        if midpoint is not None and midpoint >= self.entry_fill_price * 1.50:
            self.SubmitExit("50% profit target")
            return

        if (
            self.Time.hour == 15
            and self.Time.minute == 45
            and self.contract_expiry is not None
            and self.Time.date() == self.PreviousTradingDate(self.contract_expiry)
        ):
            self.SubmitExit("Pre-expiration time stop")

    def CheckExpirationProcessing(self):
        if (
            self.contract_expiry is not None
            and self.Time.date() >= self.contract_expiry
            and self.exit_ticket is None
        ):
            self.no_entry_date = self.Time.date()
            self.Debug("Expiration processing with open option; liquidating.")
            self.SubmitExit("Expiration processing liquidation")

    def GetHeldContractMidpoint(self, data: Slice):
        if data.OptionChains.Count == 0:
            return None

        for chain in data.OptionChains.Values:
            for contract in chain.Contracts.Values:
                if contract.Symbol != self.held_contract:
                    continue

                bid = contract.BidPrice
                ask = contract.AskPrice
                if bid > 0 and ask > 0:
                    return (bid + ask) / 2.0

        return None

    def SubmitExit(self, reason: str):
        if self.held_contract is None or self.exit_ticket is not None:
            return

        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity == 0:
            return

        for order in self.Transactions.GetOpenOrders(self.held_contract):
            if self.entry_ticket is None or order.Id != self.entry_ticket.OrderId:
                self.Transactions.CancelOrder(order.Id, "Replacing open exit order")

        self.Debug(f"Exit submitted: {reason}.")
        self.exit_ticket = self.MarketOrder(
            self.held_contract,
            -quantity,
            tag=reason
        )

    def PreviousTradingDate(self, expiration_date):
        candidate = expiration_date - timedelta(days=1)
        hours = self.Securities[self.spy].Exchange.Hours

        while not hours.IsDateOpen(datetime.combine(candidate, datetime.min.time())):
            candidate -= timedelta(days=1)

        return candidate

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled and order_event.FillQuantity > 0:
                self.held_contract = order_event.Symbol
                self.entry_fill_price = order_event.FillPrice
                self.contract_expiry = order_event.Symbol.ID.Date.date()
                self.entry_ticket = None
                self.Debug(
                    f"Entry filled: {self.held_contract} at {self.entry_fill_price:.2f}."
                )
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.entry_ticket = None

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(f"Exit filled: {order_event.Symbol} at {order_event.FillPrice:.2f}.")
                self.exit_ticket = None
                self.held_contract = None
                self.entry_fill_price = None
