        self.entry_order_id = None
        self.exit_order_id = None
        self.exit_pending = False
        self.time_stop_date = None
        self.expiration_block_date = None
        self.equity_liquidation_pending = False

        consolidator = TradeBarConsolidator(self.FiveMinuteCalendar)
        consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, consolidator)

        self.Schedule.On(
            self.DateRules.EveryDay(self.spy),
            self.TimeRules.At(15, 45, TimeZones.NewYork),
            self.CheckTimeStop
        )

    def FiveMinuteCalendar(self, time):
        start = time.replace(
            minute=time.minute - (time.minute % 5),
            second=0,
            microsecond=0
        )
        return CalendarInfo(start, start + timedelta(minutes=5))

    def OnData(self, data):
        self.HandleUnexpectedSpyEquity()

        if self.held_contract is not None:
            if self.held_contract.ID.Date.date() <= self.Time.date():
                self.expiration_block_date = self.Time.date()
                self.Debug(f"Expiration safety exit: {self.held_contract}")
                self.SubmitExitOrder("expiration safety")
                return

            self.CheckProfitTarget(data)

    def OnFiveMinuteBar(self, sender, bar):
        self.five_minute_closes.Add(float(bar.Close))

        if not self.five_minute_closes.IsReady:
            return

        fast = sum(self.five_minute_closes[i] for i in range(5)) / 5.0
        slow = sum(self.five_minute_closes[i] for i in range(20)) / 20.0

        bullish_cross = (
            self.previous_fast is not None and
            self.previous_fast <= self.previous_slow and
            fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow

        end_time = bar.EndTime.time()
        eligible_time = (
            end_time >= datetime.strptime("09:45", "%H:%M").time() and
            end_time <= datetime.strptime("14:30", "%H:%M").time()
        )

        if bullish_cross and eligible_time:
            self.TryEnterCall()

    def TryEnterCall(self):
        if self.held_contract is not None or self.pending_entry_symbol is not None:
            return

        if self.expiration_block_date == self.Time.date():
            return

        current_slice = self.CurrentSlice
        if current_slice is None or current_slice.OptionChains.Count == 0:
            self.Debug("Entry skipped: no option chain in current Slice")
            return

        minimum_expiry = self.Time.date() + timedelta(days=7)
        contracts = []

        for chain in current_slice.OptionChains.Values:
            for contract in chain.Contracts.Values:
                if (
                    contract.Right == OptionRight.Call and
                    contract.Expiry.date() >= minimum_expiry
                ):
                    contracts.append(contract)

        if not contracts:
            self.Debug("Entry skipped: no eligible call expiration")
            return

        selected_expiry = min(contract.Expiry.date() for contract in contracts)
        expiry_calls = [
            contract for contract in contracts
            if contract.Expiry.date() == selected_expiry
        ]

        if not expiry_calls:
            self.Debug("Entry skipped: no calls at selected expiration")
            return

        spot = float(self.Securities[self.spy].Price)
        if spot <= 0:
            self.Debug("Entry skipped: invalid SPY price")
            return

        selected = min(
            expiry_calls,
            key=lambda contract: (abs(float(contract.Strike) - spot), float(contract.Strike))
        )

        self.pending_entry_symbol = selected.Symbol
        ticket = self.MarketOrder(selected.Symbol, 1)
        if self.pending_entry_symbol is not None:
            self.entry_order_id = ticket.OrderId

        self.Debug(
            f"Entry submitted: {selected.Symbol} exp {selected.Expiry.date()} "
            f"strike {selected.Strike}"
        )

