        if self.entry_price is None or self.entry_price <= 0 or self.exit_pending:
            return

        contract = self.GetHeldContractFromSlice(data)
        if contract is None:
            return

        bid = float(contract.BidPrice)
        ask = float(contract.AskPrice)
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self.Debug(f"Profit target exit: {self.held_contract} midpoint {midpoint:.2f}")
            self.SubmitExitOrder("profit target")

    def CheckTimeStop(self):
        if self.held_contract is None or self.exit_pending:
            return

        if self.time_stop_date == self.Time.date():
            self.Debug(f"Time-stop exit: {self.held_contract}")
            self.SubmitExitOrder("time stop")

    def SubmitExitOrder(self, reason):
        if self.held_contract is None or self.exit_pending:
            return

        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity == 0:
            return

        self.Transactions.CancelOpenOrders(self.held_contract)
        self.exit_pending = True
        ticket = self.MarketOrder(self.held_contract, -quantity)

        if self.exit_pending:
            self.exit_order_id = ticket.OrderId

        self.Debug(f"Exit submitted ({reason}): {self.held_contract}")

    def GetHeldContractFromSlice(self, data):
        for chain in data.OptionChains.Values:
            if self.held_contract in chain.Contracts:
                return chain.Contracts[self.held_contract]
        return None

    def PreviousTradingDay(self, expiry_date):
        candidate = expiry_date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate

    def HandleUnexpectedSpyEquity(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity != 0 and not self.equity_liquidation_pending:
            self.equity_liquidation_pending = True
            self.Debug(f"Unexpected SPY exercise/assignment position: {quantity}; liquidating")
            self.MarketOrder(self.spy, -quantity)

    def OnOrderEvent(self, order_event):
        if order_event.Symbol == self.spy:
            if order_event.Status in [OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid]:
                self.equity_liquidation_pending = False
            return

        if (
            self.pending_entry_symbol is not None and
            order_event.Symbol == self.pending_entry_symbol
        ):
            if order_event.FillQuantity > 0 and order_event.FillPrice > 0:
                self.held_contract = order_event.Symbol
                self.entry_price = float(order_event.FillPrice)
                self.pending_entry_symbol = None
                self.time_stop_date = self.PreviousTradingDay(
                    self.held_contract.ID.Date.date()
                )
                self.Debug(
                    f"Entry filled: {self.held_contract} at {self.entry_price:.2f}"
                )
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.Debug(f"Entry canceled or invalid: {order_event.Symbol}")
                self.pending_entry_symbol = None
                self.entry_order_id = None
            return

        if self.held_contract is not None and order_event.Symbol == self.held_contract:
            if order_event.FillQuantity < 0 and self.Portfolio[order_event.Symbol].Quantity == 0:
                self.Debug(f"Exit filled: {order_event.Symbol} at {order_event.FillPrice:.2f}")
                self.held_contract = None
                self.entry_price = None
                self.exit_order_id = None
                self.exit_pending = False
                self.time_stop_date = None
            elif (
                self.exit_order_id == order_event.OrderId and
                order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]
            ):
                self.exit_order_id = None
                self.exit_pending = False

