from AlgorithmImports import *
from collections import deque
from datetime import timedelta


class SpyFiveMinuteCallCrossover(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            data_normalization_mode=DataNormalizationMode.Raw
        ).Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe.IncludeWeeklys()
            .Strikes(-50, 50)
            .Expiration(0, 180)
        )
        self.option_symbol = option.Symbol

        self._five_minute_closes = deque(maxlen=20)
        self._previous_fast = None
        self._previous_slow = None
        self._pending_signal_end = None

        self._held_contract = None
        self._held_expiration = None
        self._entry_price = None
        self._entry_order_id = None
        self._exit_order_id = None
        self._block_entries_on_date = None

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, consolidator)

    def OnFiveMinuteBar(self, sender, bar):
        self._five_minute_closes.append(bar.Close)

        if len(self._five_minute_closes) < 20:
            return

        closes = list(self._five_minute_closes)
        fast = sum(closes[-5:]) / 5.0
        slow = sum(closes) / 20.0

        crossed_up = (
            self._previous_fast is not None
            and self._previous_slow is not None
            and self._previous_fast <= self._previous_slow
            and fast > slow
        )

        self._previous_fast = fast
        self._previous_slow = slow

        end_time = bar.EndTime
        if crossed_up and (
            (end_time.hour == 9 and end_time.minute >= 45)
            or 10 <= end_time.hour <= 13
            or (end_time.hour == 14 and end_time.minute <= 30)
        ):
            self._pending_signal_end = end_time

    def OnData(self, data):
        self.HandleUnexpectedSpyPosition()
        self.HandleExpirationProcessing()

        if self._held_contract is not None and self.Portfolio[self._held_contract].Quantity > 0:
            self.HandleTimeStop()
            self.HandleProfitTarget(data)

        if self._pending_signal_end is not None:
            if self._pending_signal_end == self.Time:
                self.TryEnter(data)
            self._pending_signal_end = None

    def TryEnter(self, data):
        if self._block_entries_on_date == self.Time.date():
            return

        if self._entry_order_id is not None:
            return

        if self._held_contract is not None and self.Portfolio[self._held_contract].Quantity != 0:
            return

        if not data.OptionChains.ContainsKey(self.option_symbol):
            self.Debug("Entry skipped: no SPY option chain.")
            return

        chain = data.OptionChains[self.option_symbol]
        today = self.Time.date()

        eligible_expirations = sorted({
            contract.Expiry.date()
            for contract in chain.Contracts.Values
            if contract.Expiry.date() >= today + timedelta(days=7)
        })

        if not eligible_expirations:
            self.Debug("Entry skipped: no expiration at least 7 calendar days away.")
            return

        selected_expiration = eligible_expirations[0]
        calls = [
            contract for contract in chain.Contracts.Values
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == selected_expiration
        ]

        underlying_price = self.Securities[self.spy].Price
        if not calls or underlying_price <= 0:
            self.Debug("Entry skipped: no eligible call contract.")
            return

        contract = min(calls, key=lambda c: abs(c.Strike - underlying_price))

        self._held_contract = contract.Symbol
        self._held_expiration = contract.Expiry.date()
        ticket = self.MarketOrder(contract.Symbol, 1)

