from AlgorithmImports import *
from datetime import timedelta


class FiveMinuteSpyCallCrossoverAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NEW_YORK)

        self.spy = self.AddEquity(
            "SPY",
            Resolution.MINUTE,
            data_normalization_mode=DataNormalizationMode.RAW
        ).Symbol

        option = self.AddOption("SPY", Resolution.MINUTE)
        option.SetFilter(lambda universe: universe.IncludeWeeklys()
                         .Strikes(-100, 100)
                         .Expiration(0, 90))
        self.option_symbol = option.Symbol

        self._five_minute_closes = []
        self._previous_fast = None
        self._previous_slow = None

        self._bar_bucket_end = None
        self._bucket_close = None
        self._bucket_count = 0
        self._last_minute_end = None

        self._held_contract = None
        self._entry_price = None
        self._entry_order_id = None
        self._exit_order_id = None
        self._blocked_entry_dates = set()

    def OnData(self, slice):
        self._handle_unexpected_spy_position()
        self._handle_expiration_protection()
        self._evaluate_option_exit(slice)
        self._update_five_minute_bars(slice)

    def _update_five_minute_bars(self, slice):
        if self.spy not in slice.Bars:
            return

        bar = slice.Bars[self.spy]
        minute_end = bar.EndTime

        if minute_end.time() <= time(9, 30) or minute_end.time() > time(16, 0):
            return

        bucket_end = minute_end.replace(
            minute=((minute_end.minute - 1) // 5 + 1) * 5,
            second=0,
            microsecond=0
        )

        if bucket_end.minute == 60:
            bucket_end = bucket_end.replace(minute=0) + timedelta(hours=1)

        if self._bar_bucket_end is None or bucket_end != self._bar_bucket_end:
            self._finalize_five_minute_bar(slice)

            self._bar_bucket_end = bucket_end
            self._bucket_close = bar.Close
            self._bucket_count = 1
            self._last_minute_end = minute_end
            return

        if self._last_minute_end is not None and minute_end - self._last_minute_end == timedelta(minutes=1):
            self._bucket_count += 1
        else:
            self._bucket_count = 1

        self._bucket_close = bar.Close
        self._last_minute_end = minute_end

    def _finalize_five_minute_bar(self, slice):
        if self._bar_bucket_end is None or self._bucket_count != 5:
            return

        self._five_minute_closes.append(self._bucket_close)
        if len(self._five_minute_closes) > 20:
            self._five_minute_closes.pop(0)

        if len(self._five_minute_closes) < 20:
            return

        fast = sum(self._five_minute_closes[-5:]) / 5.0
        slow = sum(self._five_minute_closes) / 20.0

        bullish_cross = (
            self._previous_fast is not None
            and self._previous_slow is not None
            and self._previous_fast <= self._previous_slow
            and fast > slow
        )

        self._previous_fast = fast
        self._previous_slow = slow

        if not bullish_cross:
            return

        bar_time = self._bar_bucket_end.time()
        if time(9, 45) <= bar_time <= time(14, 30):
            self._try_enter(slice)

    def _try_enter(self, slice):
        if self.Time.date() in self._blocked_entry_dates:
            return

        if self._entry_order_id is not None or self._has_option_holding():
            return

        if self.option_symbol not in slice.OptionChains:
            self.Debug(f"{self.Time}: Entry skipped: no SPY option chain.")
            return

        chain = slice.OptionChains[self.option_symbol]
        minimum_expiry = self.Time.date() + timedelta(days=7)

        expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Right == OptionRight.CALL
            and contract.Expiry.date() >= minimum_expiry
        })

        if not expirations:
            self.Debug(f"{self.Time}: Entry skipped: no call expiry at least 7 calendar days away.")
            return

        selected_expiry = expirations[0]
        calls = [
            contract for contract in chain
            if contract.Right == OptionRight.CALL
            and contract.Expiry.date() == selected_expiry
        ]

        if not calls:
            self.Debug(f"{self.Time}: Entry skipped: no eligible calls at selected expiry.")
            return

        underlying_price = self.Securities[self.spy].Price
        selected = min(calls, key=lambda contract: (abs(contract.Strike - underlying_price), contract.Strike))

        ticket = self.MarketOrder(selected.Symbol, 1)
        self._entry_order_id = ticket.OrderId
        self._held_contract = selected.Symbol
        self.Debug(
            f"{self.Time}: Entry submitted for {selected.Symbol.Value}, "
            f"expiry {selected.Expiry.date()}, strike {selected.Strike}."
        )

    def _evaluate_option_exit(self, slice):
        if not self._has_option_holding() or self._held_contract is None:
            return

        if self._exit_order_id is not None:
            return

        if self._entry_price is not None:
            quote_contract = None
            for chain in slice.OptionChains.Values:
                for contract in chain:
                    if contract.Symbol == self._held_contract:
                        quote_contract = contract
                        break
                if quote_contract is not None:
                    break

            if quote_contract is not None:
                bid = quote_contract.BidPrice
                ask = quote_contract.AskPrice
                if bid > 0 and ask > 0:
                    midpoint = (bid + ask) / 2.0
                    if midpoint >= self._entry_price * 1.50:
                        self._submit_exit("profit target")
                        return

        if self.Time.time() == time(15, 45) and self._is_previous_trading_day():
            self._submit_exit("pre-expiration time stop")

    def _handle_expiration_protection(self):
        if not self._has_option_holding() or self._held_contract is None:
            return

        expiry = self._held_contract.ID.Date.date()
        if self.Time.date() >= expiry:
            self._blocked_entry_dates.add(self.Time.date())
            self._submit_exit("expiration protection")

    def _is_previous_trading_day(self):
        if self._held_contract is None:
            return False

        expiry = self._held_contract.ID.Date.date()
        candidate = expiry - timedelta(days=1)

        while not self.Securities[self.spy].Exchange.Hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return self.Time.date() == candidate

    def _submit_exit(self, reason):
        if self._held_contract is None or self._exit_order_id is not None:
            return

        quantity = self.Securities[self._held_contract].Holdings.Quantity
        if quantity == 0:
            return

        ticket = self.MarketOrder(self._held_contract, -quantity)
        self._exit_order_id = ticket.OrderId
        self.Debug(f"{self.Time}: Exit submitted for {self._held_contract.Value}: {reason}.")

    def _handle_unexpected_spy_position(self):
        quantity = self.Securities[self.spy].Holdings.Quantity
        if quantity != 0:
            self.Debug(
                f"{self.Time}: Unexpected SPY equity position ({quantity}) from exercise/assignment; liquidating."
            )
            self.MarketOrder(self.spy, -quantity)

    def _has_option_holding(self):
        return (
            self._held_contract is not None
            and self._held_contract in self.Securities
            and self.Securities[self._held_contract].Holdings.Quantity != 0
        )

    def OnOrderEvent(self, order_event):
        if self._entry_order_id == order_event.OrderId:
            if order_event.Status == OrderStatus.FILLED:
                self._entry_price = order_event.FillPrice
                self._entry_order_id = None
                self.Debug(
                    f"{self.Time}: Entry filled for {order_event.Symbol.Value} "
                    f"at {order_event.FillPrice}."
                )
            elif order_event.Status in [OrderStatus.CANCELED, OrderStatus.INVALID]:
                self.Debug(f"{self.Time}: Entry order {order_event.OrderId} did not fill.")
                self._entry_order_id = None
                self._held_contract = None
                self._entry_price = None

        if self._exit_order_id == order_event.OrderId:
            if order_event.Status == OrderStatus.FILLED:
                self.Debug(
                    f"{self.Time}: Exit filled for {order_event.Symbol.Value} "
                    f"at {order_event.FillPrice}."
                )
                self._exit_order_id = None
                if not self._has_option_holding():
                    self._held_contract = None
                    self._entry_price = None
            elif order_event.Status in [OrderStatus.CANCELED, OrderStatus.INVALID]:
                self._exit_order_id = None

