        self.entry_signal_pending = False

        self.held_contract = None
        self.held_expiry = None
        self.entry_price = None

        self.entry_order_id = None
        self.exit_order_id = None
        self.equity_exit_order_id = None
        self.no_entry_date = None

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, consolidator)

    def OnFiveMinuteBar(self, bar):
        bar_time = bar.EndTime.time()

        # With regular-hours SPY minute data, the first valid session bar ends 09:35.
        if bar_time < time(9, 35) or bar_time > time(16, 0):
            return

        self.closes.Add(float(bar.Close))
        if not self.closes.IsReady:
            return

        fast = sum(self.closes[i] for i in range(5)) / 5.0
        slow = sum(self.closes[i] for i in range(20)) / 20.0

        bullish_cross = (
            self.previous_fast is not None
            and self.previous_fast <= self.previous_slow
            and fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow

        if (
            bullish_cross
            and time(9, 45) <= bar_time <= time(14, 30)
        ):
            self.entry_signal_pending = True

    def OnData(self, slice):
        today = self.Time.date()

        # Handle an unexpected exercise/assignment-created equity position.
        if self.Portfolio[self.spy].Quantity != 0:
            self.no_entry_date = today
            if self.equity_exit_order_id is None:
                quantity = -self.Portfolio[self.spy].Quantity
                ticket = self.MarketOrder(self.spy, quantity)
                self.equity_exit_order_id = ticket.OrderId
                self.Debug(
                    f"Unexpected SPY equity position; liquidating {quantity} shares."
                )

        # Never intentionally hold an option into its expiration date.
        if self.held_contract is not None and self.held_expiry is not None:
            if today >= self.held_expiry.date():
                self.no_entry_date = today
                self.entry_signal_pending = False
                if self.Portfolio[self.held_contract].Quantity != 0:
                    self.SubmitExit("expiration processing")
                return

        if self.held_contract is not None and self.Portfolio[self.held_contract].Quantity != 0:
            self.EvaluateOptionExit(slice)

        if not self.entry_signal_pending:
            return

        self.entry_signal_pending = False

        if self.no_entry_date == today:
            self.Debug("Skipped entry: expiration or assignment handling is active today.")
            return

        if self.held_contract is not None and self.Portfolio[self.held_contract].Quantity != 0:
            return

        if self.entry_order_id is not None:
            return

        self.TryEnter(slice)

    def TryEnter(self, slice):
        if self.option_symbol not in slice.OptionChains:
            self.Debug("Skipped entry: no SPY option chain in current Slice.")
            return

        chain = slice.OptionChains[self.option_symbol]
        minimum_expiry = self.Time.date() + timedelta(days=7)

        eligible = [
            contract for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() >= minimum_expiry
        ]

        if not eligible:
            self.Debug("Skipped entry: no call expiration at least 7 calendar days away.")
            return

        selected_expiry = min(contract.Expiry.date() for contract in eligible)
        calls = [
            contract for contract in eligible
            if contract.Expiry.date() == selected_expiry
        ]

        if not calls:
            self.Debug("Skipped entry: no eligible calls at selected expiration.")
            return

        spot = float(self.Securities[self.spy].Price)
        if spot <= 0:
            self.Debug("Skipped entry: SPY has no valid current price.")
            return

        # Select the call with the strike nearest the current SPY price.
        contract = min(
            calls,
            key=lambda candidate: (
                abs(float(candidate.Strike) - spot),
                float(candidate.Strike)
            )
        )

        self.held_contract = contract.Symbol
        self.held_expiry = contract.Expiry
        ticket = self.MarketOrder(contract.Symbol, 1)
        self.entry_order_id = ticket.OrderId

        self.Debug(
            f"Entry submitted: {contract.Symbol} exp {contract.Expiry.date()} "
            f"strike {contract.Strike}."
        )

    def EvaluateOptionExit(self, slice):
        if self.exit_order_id is not None:
            return

        if (
            self.Time.hour == 15
            and self.Time.minute == 45
            and self.IsDayBeforeExpiration()
        ):
            self.SubmitExit("day-before-expiration time stop")
            return

        if self.entry_price is None:
            return

        contract = self.GetHeldContractFromSlice(slice)
        if contract is None:
            return

        bid = float(contract.BidPrice)
        ask = float(contract.AskPrice)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self.CancelOpenExitOrders()
            self.SubmitExit("50% profit target")

    def GetHeldContractFromSlice(self, slice):
        if self.option_symbol not in slice.OptionChains:
            return None

        for contract in slice.OptionChains[self.option_symbol]:
            if contract.Symbol == self.held_contract:
                return contract

        return None

    def IsDayBeforeExpiration(self):
        previous_trading_day = (
            self.Securities[self.spy].Exchange.Hours
            .GetPreviousTradingDay(self.held_expiry)
        )
        return self.Time.date() == previous_trading_day.date()

    def CancelOpenExitOrders(self):
        if self.held_contract is None:
            return

        for order in self.Transactions.GetOpenOrders(self.held_contract):
            if order.Id != self.entry_order_id:
                self.Transactions.CancelOrder(order.Id)

        self.exit_order_id = None

    def SubmitExit(self, reason):
        if self.held_contract is None or self.exit_order_id is not None:
            return

        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity == 0:
            return

        ticket = self.MarketOrder(self.held_contract, -quantity)
        self.exit_order_id = ticket.OrderId
        self.Debug(f"Exit submitted ({reason}): {self.held_contract}.")

    def OnOrderEvent(self, order_event):
        if order_event.OrderId == self.entry_order_id:
            if order_event.Status in [OrderStatus.PartiallyFilled, OrderStatus.Filled]:
                if order_event.FillPrice > 0 and self.entry_price is None:
                    self.entry_price = float(order_event.FillPrice)
                    self.Debug(
                        f"Entry filled: {self.held_contract} at {self.entry_price:.2f}."
                    )

            if order_event.Status in [
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ]:
                self.entry_order_id = None

            return

        if order_event.OrderId == self.exit_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(f"Exit filled: {self.held_contract}.")
                self.held_contract = None
                self.held_expiry = None
                self.entry_price = None
                self.exit_order_id = None
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.exit_order_id = None

            return

        if order_event.OrderId == self.equity_exit_order_id:
            if order_event.Status in [
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ]:
                self.equity_exit_order_id = None

