from AlgorithmImports import *
from datetime import timedelta, time


class FiveMinuteSpyCallCrossover(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        spy = self.AddEquity("SPY", Resolution.Minute)
        spy.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy_symbol = spy.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe.IncludeWeeklys()
            .Strikes(-200, 200)
            .Expiration(7, 365)
        )
        self.option_symbol = option.Symbol

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)
        self.previous_fast = None
        self.previous_slow = None

        self.pending_entry_bar_end = None
        self.blocked_entry_date = None

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_contract = None
        self.entry_price = None

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy_symbol, consolidator)

    def OnFiveMinuteBar(self, sender, bar):
        prior_fast = self.previous_fast
        prior_slow = self.previous_slow

        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        if self.fast.IsReady and self.slow.IsReady:
            if prior_fast is not None and prior_slow is not None:
                clock = bar.EndTime.time()
                is_entry_time = time(9, 45) <= clock <= time(14, 30)

                if (is_entry_time and
                        prior_fast <= prior_slow and
                        self.fast.Current.Value > self.slow.Current.Value):
                    self.pending_entry_bar_end = bar.EndTime

            self.previous_fast = self.fast.Current.Value
            self.previous_slow = self.slow.Current.Value

    def OnData(self, data):
        today = self.Time.date()

        if self.blocked_entry_date is not None and self.blocked_entry_date != today:
            self.blocked_entry_date = None

        self.HandleUnexpectedSpyEquity()

        if self.held_contract is not None:
            self.HandleExpirationProtection()
            self.HandleTimeStop()
            self.HandleProfitTarget(data)

        if self.pending_entry_bar_end is not None:
            if self.Time >= self.pending_entry_bar_end:
                if self.Time == self.pending_entry_bar_end:
                    self.TryEnter(data)
                self.pending_entry_bar_end = None

    def TryEnter(self, data):
        if self.blocked_entry_date == self.Time.date():
            return

        if self.held_contract is not None or self.HasOpenEntryOrder():
            return

        contracts = []
        for chain in data.OptionChains.Values:
            for contract in chain:
                if contract.Symbol.ID.Underlying == self.spy_symbol:
                    contracts.append(contract)

        if not contracts:
            self.Debug(f"{self.Time}: entry skipped; no SPY option chain")
            return

        minimum_expiry = self.Time.date() + timedelta(days=7)
        eligible_expirations = sorted(
            {
                contract.Expiry.date()
                for contract in contracts
                if contract.Expiry.date() >= minimum_expiry
            }
        )

        if not eligible_expirations:
            self.Debug(f"{self.Time}: entry skipped; no expiration at least 7 calendar days out")
            return

        selected_expiry = eligible_expirations[0]
        calls = [
            contract for contract in contracts
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
        ]

        if not calls:
            self.Debug(f"{self.Time}: entry skipped; no calls at selected expiration")
            return

        underlying_price = self.Securities[self.spy_symbol].Price
        selected = min(
            calls,
            key=lambda contract: (abs(contract.Strike - underlying_price), contract.Strike)
        )

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            f"{self.Time}: submitted call entry {selected.Symbol} "
            f"expiry {selected.Expiry.date()}"
        )

    def HandleProfitTarget(self, data):
        if self.entry_price is None or self.HasOpenExitOrder():
            return

        quote = self.GetHeldContractQuote(data)
        if quote is None:
            return

        bid, ask = quote
        midpoint = (bid + ask) / 2.0
        if midpoint >= self.entry_price * 1.50:
            self.SubmitExit("profit target")

    def HandleTimeStop(self):
        if self.HasOpenExitOrder() or self.held_contract is None:
            return

        expiry = self.held_contract.ID.Date.date()
        prior_trading_day = expiry - timedelta(days=1)

        exchange_hours = self.Securities[self.spy_symbol].Exchange.Hours
        while not exchange_hours.IsDateOpen(prior_trading_day):
            prior_trading_day -= timedelta(days=1)

        if self.Time.date() == prior_trading_day and self.Time.time() >= time(15, 45):
            self.SubmitExit("pre-expiration time stop")

    def HandleExpirationProtection(self):
        if self.held_contract is None:
            return

        expiry = self.held_contract.ID.Date.date()
        if self.Time.date() >= expiry:
            self.blocked_entry_date = self.Time.date()
