            calls,
            key=lambda candidate: (
                abs(candidate.Strike - underlying_price),
                candidate.Strike
            )
        )

        ticket = self.MarketOrder(contract.Symbol, 1)
        self.entry_order_id = ticket.OrderId
        self.entry_symbol = contract.Symbol
        self.held_expiry = contract.Expiry

        self.Debug(
            f"{self.Time}: Entry submitted: {contract.Symbol.Value}, "
            f"expiry {contract.Expiry.date()}, strike {contract.Strike}."
        )

