        spy_holding = self.Portfolio[self.spy]
        if not spy_holding.Invested:
            return

        if self.spy_liquidation_order_id is not None:
            return

        ticket = self.MarketOrder(self.spy, -spy_holding.Quantity)
        self.spy_liquidation_order_id = ticket.OrderId
        self.Debug(
            f"{self.Time}: Unexpected SPY exercise/assignment position detected; "
            f"submitted liquidation."
        )

    def SubmitExit(self, reason):
        if self.held_symbol is None or self.exit_order_id is not None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        for order in self.Transactions.GetOpenOrders(self.held_symbol):
            if order.Id != self.entry_order_id:
                self.Transactions.CancelOrder(order.Id, "Replacing exit order")

        ticket = self.MarketOrder(self.held_symbol, -quantity)
        self.exit_order_id = ticket.OrderId
        self.Debug(f"{self.Time}: Exit submitted ({reason}): {self.held_symbol.Value}.")

    def GetHeldContract(self, data):
        for chain in data.OptionChains.Values:
            for contract in chain:
                if contract.Symbol == self.held_symbol:
                    return contract
        return None

    def OnOrderEvent(self, order_event):
        if order_event.OrderId == self.entry_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.held_symbol = self.entry_symbol
                self.entry_fill_price = order_event.FillPrice
                self.entry_order_id = None
                self.Debug(
                    f"{self.Time}: Entry filled: {self.held_symbol.Value} "
                    f"at {self.entry_fill_price}."
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.Debug(f"{self.Time}: Entry order did not fill.")
                self.entry_order_id = None
                self.entry_symbol = None
                self.held_expiry = None

        if order_event.OrderId == self.exit_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(f"{self.Time}: Exit filled: {order_event.Symbol.Value}.")
                self.exit_order_id = None
                self.held_symbol = None
                self.held_expiry = None
                self.entry_fill_price = None
                self.entry_symbol = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.exit_order_id = None

        if order_event.OrderId == self.spy_liquidation_order_id:
            if order_event.Status in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.spy_liquidation_order_id = None

