        self.slow = SimpleMovingAverage(20)

        self.five_minute_consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self.five_minute_consolidator.DataConsolidated += self.OnFiveMinuteBar

        self.minute_bars_by_end_time = {}
        self.pending_entry_time = None

        self.held_option = None
        self.entry_order_id = None
        self.entry_symbol = None
        self.entry_fill_price = None
        self.exit_order_id = None
        self.no_entry_date = None
        self.equity_liquidation_order_id = None

        self.Schedule.On(
            self.DateRules.EveryDay(self.spy),
            self.TimeRules.At(15, 45),
            self.TimeStop
        )

    def OnData(self, data):
        self.HandleUnexpectedSpyEquityPosition()

        if self.held_option is not None and self.Portfolio[self.held_option].Quantity > 0:
            if self.Time.date() == self.OptionExpiryDate(self.held_option):
                self.no_entry_date = self.Time.date()
                self.RequestOptionExit("expiration safeguard")
                return

        if self.held_option is not None and self.Portfolio[self.held_option].Quantity > 0:
            self.CheckProfitTarget(data)

        spy_bar = data.Bars[self.spy] if self.spy in data.Bars else None
        if spy_bar is not None:
            self.minute_bars_by_end_time[spy_bar.EndTime] = spy_bar
            self.five_minute_consolidator.Update(spy_bar)

            cutoff = self.Time - timedelta(minutes=15)
            stale_times = [
                end_time for end_time in self.minute_bars_by_end_time
                if end_time < cutoff
            ]
            for end_time in stale_times:
                del self.minute_bars_by_end_time[end_time]

        if self.pending_entry_time == self.Time:
            self.pending_entry_time = None
            self.TryEnter(data)

    def OnFiveMinuteBar(self, bar):
        expected_end_times = [
            bar.EndTime - timedelta(minutes=offset)
            for offset in range(5)
        ]

        if not all(end_time in self.minute_bars_by_end_time for end_time in expected_end_times):
            return

        previous_ready = self.fast.IsReady and self.slow.IsReady
        previous_fast = self.fast.Current.Value if previous_ready else None
        previous_slow = self.slow.Current.Value if previous_ready else None

        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        if not previous_ready or not self.fast.IsReady or not self.slow.IsReady:
            return

        bar_time = bar.EndTime.time()
        eligible_time = time(9, 45) <= bar_time <= time(14, 30)

        if (
            eligible_time
            and previous_fast <= previous_slow
            and self.fast.Current.Value > self.slow.Current.Value
        ):
            self.pending_entry_time = bar.EndTime

    def TryEnter(self, data):
        if self.no_entry_date == self.Time.date():
            return

        if self.held_option is not None or self.entry_symbol is not None:
            return

        if self.option_symbol not in data.OptionChains:
            self.Debug("Entry skipped: no SPY option chain.")
            return

        chain = data.OptionChains[self.option_symbol]
        minimum_expiry_date = self.Time.date() + timedelta(days=7)

        eligible_contracts = [
            contract for contract in chain
            if contract.Right == OptionRight.CALL
            and contract.Expiry.date() >= minimum_expiry_date
        ]

        if not eligible_contracts:
            self.Debug("Entry skipped: no call expiration at least 7 calendar days away.")
            return

        selected_expiry = min(contract.Expiry.date() for contract in eligible_contracts)
        calls_at_expiry = [
            contract for contract in eligible_contracts
            if contract.Expiry.date() == selected_expiry
        ]

        if not calls_at_expiry:
            self.Debug("Entry skipped: no eligible calls at selected expiration.")
            return

        underlying_price = self.Securities[self.spy].Price
        selected_contract = min(
            calls_at_expiry,
            key=lambda contract: (abs(contract.Strike - underlying_price), contract.Strike)
        )

        self.entry_symbol = selected_contract.Symbol
        self.entry_order_id = -1
        ticket = self.MarketOrder(selected_contract.Symbol, 1)

        if self.entry_symbol is not None:
            self.entry_order_id = ticket.OrderId

        self.Debug(
            f"Entry submitted: {selected_contract.Symbol} "
            f"expiry {selected_contract.Expiry.date()}."
        )

    def CheckProfitTarget(self, data):
        if self.exit_order_id is not None:
            return

        contract = self.GetHeldContractFromSlice(data)
        if contract is None or contract.BidPrice <= 0 or contract.AskPrice <= 0:
            return

        midpoint = (contract.BidPrice + contract.AskPrice) / 2.0
        if self.entry_fill_price is not None and midpoint >= self.entry_fill_price * 1.50:
            self.RequestOptionExit("50% profit target")

    def TimeStop(self):
        if self.held_option is None or self.Portfolio[self.held_option].Quantity <= 0:
            return

        expiry_date = self.OptionExpiryDate(self.held_option)
        previous_trading_day = self.PreviousSpyTradingDay(expiry_date)

        if self.Time.date() == previous_trading_day:
            self.RequestOptionExit("15:45 pre-expiration time stop")

    def RequestOptionExit(self, reason):
        if self.held_option is None or self.exit_order_id is not None:
            return

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity <= 0:
            return

        for order in self.Transactions.GetOpenOrders(self.held_option):
            if order.Direction == OrderDirection.SELL:
                self.Transactions.CancelOrder(order.Id)

        symbol = self.held_option
        self.exit_order_id = -1
        ticket = self.MarketOrder(symbol, -quantity)

        if self.held_option == symbol:
            self.exit_order_id = ticket.OrderId

        self.Debug(f"Exit submitted: {reason} for {symbol}.")

    def HandleUnexpectedSpyEquityPosition(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity == 0 or self.equity_liquidation_order_id is not None:
            return

        self.equity_liquidation_order_id = -1
        ticket = self.MarketOrder(self.spy, -quantity)
        self.equity_liquidation_order_id = ticket.OrderId
        self.Debug("Unexpected SPY exercise/assignment position: liquidation submitted.")

    def GetHeldContractFromSlice(self, data):
        if self.held_option is None or self.option_symbol not in data.OptionChains:
            return None

        for contract in data.OptionChains[self.option_symbol]:
            if contract.Symbol == self.held_option:
                return contract

        return None

    def OptionExpiryDate(self, symbol):
        return symbol.ID.Date.date()

    def PreviousSpyTradingDay(self, expiry_date):
        candidate = datetime.combine(expiry_date, time.min) - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate.date()

    def OnOrderEvent(self, order_event):
        if (
            self.entry_symbol is not None
            and order_event.Symbol == self.entry_symbol
            and order_event.Direction == OrderDirection.BUY
        ):
            if order_event.Status == OrderStatus.FILLED:
                self.held_option = order_event.Symbol
                self.entry_fill_price = order_event.FillPrice
                self.entry_symbol = None
                self.entry_order_id = None
                self.Debug(
                    f"Entry filled: {self.held_option} at {self.entry_fill_price:.2f}."
                )
            elif order_event.Status in [OrderStatus.CANCELED, OrderStatus.INVALID]:
                self.Debug(f"Entry failed: {order_event.Symbol}.")
                self.entry_symbol = None
                self.entry_order_id = None

        if (
            self.held_option is not None
            and order_event.Symbol == self.held_option
            and order_event.Direction == OrderDirection.SELL
            and order_event.Status == OrderStatus.FILLED
        ):
            self.Debug(f"Exit filled: {self.held_option} at {order_event.FillPrice:.2f}.")
            self.held_option = None
            self.entry_fill_price = None
            self.exit_order_id = None

        if (
            order_event.Symbol == self.spy
            and order_event.Direction != OrderDirection.HOLD
            and order_event.Status == OrderStatus.FILLED
        ):
            self.equity_liquidation_order_id = None

